const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n }, () => []);
for (let i = 0; i < m; i++) adj[tok[2 + 2 * i] - 1].push(tok[3 + 2 * i] - 1);
const tin = new Array(n).fill(-1), low = new Array(n).fill(0), onStack = new Array(n).fill(false);
const comp = new Array(n).fill(-1);
const stack = [];
let timer = 0, ncomp = 0;
function dfs(u) {
  tin[u] = low[u] = timer++;
  stack.push(u); onStack[u] = true;
  for (const v of adj[u]) {
    if (tin[v] < 0) { dfs(v); low[u] = Math.min(low[u], low[v]); }
    else if (onStack[v]) low[u] = Math.min(low[u], tin[v]);
  }
  if (low[u] === tin[u]) {
    for (;;) {
      const w = stack.pop(); onStack[w] = false; comp[w] = ncomp;
      if (w === u) break;
    }
    ncomp++;
  }
}
for (let u = 0; u < n; u++) if (tin[u] < 0) dfs(u);
const hasIn = new Array(ncomp).fill(false), hasOut = new Array(ncomp).fill(false);
for (let u = 0; u < n; u++) for (const v of adj[u]) if (comp[u] !== comp[v]) { hasOut[comp[u]] = true; hasIn[comp[v]] = true; }
if (ncomp === 1) console.log("0");
else {
  let sources = 0, sinks = 0;
  for (let c = 0; c < ncomp; c++) { if (!hasIn[c]) sources++; if (!hasOut[c]) sinks++; }
  console.log(String(Math.max(sources, sinks)));
}

