import java.io.*;
import java.util.*;

public class Main {
    static ArrayList<Integer>[] adj;
    static int[] tin, low, comp;
    static boolean[] onStack;
    static ArrayDeque<Integer> stack = new ArrayDeque<>();
    static int timer = 0, ncomp = 0;

    static void dfs(int u) {
        tin[u] = low[u] = timer++;
        stack.push(u);
        onStack[u] = true;
        for (int v : adj[u]) {
            if (tin[v] < 0) {
                dfs(v);
                low[u] = Math.min(low[u], low[v]);
            } else if (onStack[v]) {
                low[u] = Math.min(low[u], tin[v]);
            }
        }
        if (low[u] == tin[u]) {
            while (true) {
                int w = stack.pop();
                onStack[w] = false;
                comp[w] = ncomp;
                if (w == u) break;
            }
            ncomp++;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        Thread t = new Thread(null, () -> {
            try {
                StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
                in.nextToken();
                int n = (int) in.nval;
                in.nextToken();
                int m = (int) in.nval;
                adj = new ArrayList[n];
                for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
                for (int i = 0; i < m; i++) {
                    in.nextToken(); int u = (int) in.nval - 1;
                    in.nextToken(); int v = (int) in.nval - 1;
                    adj[u].add(v);
                }
                tin = new int[n]; low = new int[n]; comp = new int[n];
                onStack = new boolean[n];
                Arrays.fill(tin, -1);
                for (int u = 0; u < n; u++) if (tin[u] < 0) dfs(u);
                boolean[] hasIn = new boolean[ncomp], hasOut = new boolean[ncomp];
                for (int u = 0; u < n; u++)
                    for (int v : adj[u])
                        if (comp[u] != comp[v]) { hasOut[comp[u]] = true; hasIn[comp[v]] = true; }
                if (ncomp == 1) { System.out.println(0); return; }
                int sources = 0, sinks = 0;
                for (int c = 0; c < ncomp; c++) { if (!hasIn[c]) sources++; if (!hasOut[c]) sinks++; }
                System.out.println(Math.max(sources, sinks));
            } catch (IOException e) { throw new RuntimeException(e); }
        }, "main", 1 << 26);
        t.start();
        t.join();
    }
}

