#include <bits/stdc++.h>
using namespace std;
int n, m, timer_ = 0, ncomp = 0;
vector<vector<int>> adj;
vector<int> tin, low, comp, stk;
vector<bool> on_stack;
void dfs(int u) {
    tin[u] = low[u] = timer_++;
    stk.push_back(u);
    on_stack[u] = true;
    for (int v : adj[u]) {
        if (tin[v] < 0) { dfs(v); low[u] = min(low[u], low[v]); }
        else if (on_stack[v]) low[u] = min(low[u], tin[v]);
    }
    if (low[u] == tin[u]) {
        while (true) {
            int w = stk.back(); stk.pop_back();
            on_stack[w] = false;
            comp[w] = ncomp;
            if (w == u) break;
        }
        ncomp++;
    }
}
int main() {
    scanf("%d %d", &n, &m);
    adj.assign(n, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u - 1].push_back(v - 1);
    }
    tin.assign(n, -1); low.assign(n, 0); comp.assign(n, -1);
    on_stack.assign(n, false);
    for (int u = 0; u < n; u++) if (tin[u] < 0) dfs(u);
    vector<bool> has_in(ncomp, false), has_out(ncomp, false);
    for (int u = 0; u < n; u++)
        for (int v : adj[u])
            if (comp[u] != comp[v]) { has_out[comp[u]] = true; has_in[comp[v]] = true; }
    if (ncomp == 1) { puts("0"); return 0; }
    int sources = 0, sinks = 0;
    for (int c = 0; c < ncomp; c++) { if (!has_in[c]) sources++; if (!has_out[c]) sinks++; }
    printf("%d\n", max(sources, sinks));
    return 0;
}
